def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    """
    List SKUs whose stock has not moved out for a long time (dead stock).
    """
    if idle_days < 1:
        raise ValueError("idle_days must be >= 1")

    sku_on_hand: Dict[str, int] = {}
    sku_last_shp: Dict[str, int] = {}
    sku_earliest_move: Dict[str, int] = {}

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        record = parse_movement_line(stripped, case_sizes)
        day, sku, qty, mtype = record["day"], record["sku"], record["qty"], record["type"]

        if day > today:
            continue

        if sku not in sku_earliest_move or day < sku_earliest_move[sku]:
            sku_earliest_move[sku] = day

        sku_on_hand[sku] = sku_on_hand.get(sku, 0) + qty

        if mtype == "SHP":
            if sku not in sku_last_shp or day > sku_last_shp[sku]:
                sku_last_shp[sku] = day

    dead_skus = []
    for sku, total_qty in sku_on_hand.items():
        if total_qty > 0:
            last_shp = sku_last_shp.get(sku)
            if last_shp is not None:
                if today - last_shp >= idle_days:
                    dead_skus.append(sku)
            else:
                # Never shipped, check earliest movement
                earliest = sku_earliest_move.get(sku)
                if earliest is not None and today - earliest >= idle_days:
                    dead_skus.append(sku)

    return sorted(dead_skus)
